#include <vector>
#include <list>

int main() {
    std::vector<int> v = {1, 2, 3};
    std::list<int> l = {10, 20, 30, 40};

    // 1. Copy Assignment (same type)
    std::vector<int> v2 = v; 

    // 2. Range Assignment (different type iterators)
    v.assign(l.begin(), l.end());
    // v is now {10, 20, 30, 40}

    // 3. Fill Assignment
    v.assign(5, 99); 
    // v is now {99, 99, 99, 99, 99}
}
